import{y as t,b as n,c as a,X as s}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const h=JSON.parse('{"title":"TUI Compositor Implementation Proposal","description":"","frontmatter":{},"headers":[],"relativePath":"changes/research-tui-compositor/proposal.md","filePath":"changes/research-tui-compositor/proposal.md","lastUpdated":1771753292000}'),r={name:"changes/research-tui-compositor/proposal.md"};function i(o,e,l,d,u,p){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="tui-compositor-implementation-proposal" tabindex="-1">TUI Compositor Implementation Proposal <a class="header-anchor" href="#tui-compositor-implementation-proposal" aria-label="Permalink to &quot;TUI Compositor Implementation Proposal&quot;">​</a></h1><p>undefined<strong>Date</strong>: 2026-02-18 undefined<strong>Source</strong>: <a href="./../../research/CONVERSATION_DUMP_2026-02-16_EXPANDED.html">CONVERSATION_DUMP_2026-02-16_EXPANDED.md</a> § 2 undefined<strong>Status</strong>: Proposed undefined<strong>Priority</strong>: P1</p><hr><h2 id="executive-summary" tabindex="-1">Executive Summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive Summary&quot;">​</a></h2><p>Implement a <strong>TUI Compositor</strong> (terminal user interface compositor and multiplexer) to serve as the primary dashboard and control plane for the <strong>Sitback Agent</strong> and broader <strong>thegent</strong> system. The compositor will provide GUI-like experience (menus, statusbars, dialogs) with terminal pane splitting, process management, and real-time monitoring.</p><p>undefined<strong>Key Goals</strong>:</p><ul><li>Unified control plane for agent orchestration and monitoring</li><li>GUI-like experience (menubar, statusbar, keyboard shortcuts) in terminal</li><li>Real-time process and session tracking</li><li>Session persistence and layout management</li></ul><hr><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>undefined<strong>Current State</strong>:</p><ul><li>Multiple disconnected UIs: shell prompt, separate tmux sessions, log files</li><li>Sitback and other agents lack a unified dashboard</li><li>No centralized view of running agents, tasks, and system state</li><li>Users must manually manage terminal panes and sessions</li></ul><p>undefined<strong>Desired State</strong>:</p><ul><li>Single unified TUI dashboard</li><li>Menubar navigation (File, Edit, View, Tools, Help)</li><li>Statusbar showing session/agent status in real-time</li><li>Pane splitting and layout management</li><li>Session persistence across restarts</li></ul><hr><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><h3 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>FR-ID</th><th>Description</th><th>Priority</th></tr></thead><tbody><tr><td>undefined<strong>FR-TUI-001</strong>undefined</td><td>Menubar with File/Edit/View/Tools/Help menus</td><td>P0</td></tr><tr><td>undefined<strong>FR-TUI-002</strong>undefined</td><td>Statusbar displaying current session, agent, status</td><td>P0</td></tr><tr><td>undefined<strong>FR-TUI-003</strong>undefined</td><td>Horizontal and vertical pane splitting</td><td>P0</td></tr><tr><td>undefined<strong>FR-TUI-004</strong>undefined</td><td>Terminal pane widget supporting shell interaction</td><td>P1</td></tr><tr><td>undefined<strong>FR-TUI-005</strong>undefined</td><td>Floating window support (dialogs, alerts)</td><td>P1</td></tr><tr><td>undefined<strong>FR-TUI-006</strong>undefined</td><td>Layout save/restore (via YAML or JSON)</td><td>P1</td></tr><tr><td>undefined<strong>FR-TUI-007</strong>undefined</td><td>Session persistence across application restarts</td><td>P1</td></tr><tr><td>undefined<strong>FR-TUI-008</strong>undefined</td><td>Keyboard shortcuts (Ctrl+C, Ctrl+N, Ctrl+V, etc.)</td><td>P0</td></tr><tr><td>undefined<strong>FR-TUI-009</strong>undefined</td><td>Real-time process monitoring (CPU, memory)</td><td>P2</td></tr><tr><td>undefined<strong>FR-TUI-010</strong>undefined</td><td>Integration with thegent work stream (do-next, claim, complete)</td><td>P2</td></tr><tr><td>undefined<strong>FR-TUI-011</strong>undefined</td><td>Web export via <code>textual serve</code> (optional)</td><td>P3</td></tr><tr><td>undefined<strong>FR-TUI-012</strong>undefined</td><td>Theme customization (light/dark)</td><td>P2</td></tr></tbody></table><h3 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>NFR-ID</th><th>Requirement</th><th>Target</th></tr></thead><tbody><tr><td>undefined<strong>NFR-TUI-001</strong>undefined</td><td>App startup latency</td><td>&lt;500ms</td></tr><tr><td>undefined<strong>NFR-TUI-002</strong>undefined</td><td>Pane creation latency</td><td>&lt;100ms</td></tr><tr><td>undefined<strong>NFR-TUI-003</strong>undefined</td><td>Layout switch latency</td><td>&lt;50ms</td></tr><tr><td>undefined<strong>NFR-TUI-004</strong>undefined</td><td>Memory footprint</td><td>&lt;100MB idle</td></tr><tr><td>undefined<strong>NFR-TUI-005</strong>undefined</td><td>CPU usage (idle)</td><td>&lt;2%</td></tr><tr><td>undefined<strong>NFR-TUI-006</strong>undefined</td><td>Responsiveness to user input</td><td>&lt;50ms</td></tr></tbody></table><hr><h2 id="technology-selection" tabindex="-1">Technology Selection <a class="header-anchor" href="#technology-selection" aria-label="Permalink to &quot;Technology Selection&quot;">​</a></h2><h3 id="framework-textual-python" tabindex="-1">Framework: <strong>Textual</strong> (Python) <a class="header-anchor" href="#framework-textual-python" aria-label="Permalink to &quot;Framework: **Textual** (Python)&quot;">​</a></h3><p>undefined<strong>Rationale</strong>:</p><ul><li>Written in Python (matches thegent stack)</li><li>CSS-like styling for maintainable UI code</li><li>Rich widget library (menus, buttons, inputs, trees, etc.)</li><li><code>textual serve</code> for web export (future enhancement)</li><li>Strong documentation and active community</li><li>Easy integration with Python async code</li></ul><p>undefined<strong>Alternatives Considered</strong>:</p><ul><li>undefined<strong>Ratatui (Rust)</strong>: More performant but requires Rust integration</li><li>undefined<strong>Bubble Tea (Go)</strong>: Not Python; would require separate service</li><li>undefined<strong>Zellij (Rust)</strong>: Compositor, but less control over UI</li></ul><h3 id="compositor-strategy-embedded-terminal-panes" tabindex="-1">Compositor Strategy: <strong>Embedded Terminal Panes</strong>undefined <a class="header-anchor" href="#compositor-strategy-embedded-terminal-panes" aria-label="Permalink to &quot;Compositor Strategy: **Embedded Terminal Panes**&quot;">​</a></h3><p>undefined<strong>Approach</strong>:</p><ul><li>Use Textual&#39;s <code>TerminalWidget</code> (or equivalent) to embed PTY-based terminal panes</li><li>Build custom layout manager on top</li><li>Implement session state machine</li></ul><p>undefined<strong>Alternative</strong>: Use Zellij as backend compositor + custom Textual plugin (more complex)</p><hr><h2 id="high-level-architecture" tabindex="-1">High-Level Architecture <a class="header-anchor" href="#high-level-architecture" aria-label="Permalink to &quot;High-Level Architecture&quot;">​</a></h2><h3 id="layered-model" tabindex="-1">Layered Model <a class="header-anchor" href="#layered-model" aria-label="Permalink to &quot;Layered Model&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  GUI-like Menu Layer (Textual)                   │</span></span>
<span class="line"><span>│  - Menubar (File, Edit, View, Tools, Help)      │</span></span>
<span class="line"><span>│  - Statusbar (session info, agent status)       │</span></span>
<span class="line"><span>│  - Dialogs (confirmations, inputs)              │</span></span>
<span class="line"><span>│  - Keyboard shortcuts (Ctrl+C, Ctrl+V, etc.)    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  TUI Compositor Layer                            │</span></span>
<span class="line"><span>│  - Pane management (split, merge, focus)        │</span></span>
<span class="line"><span>│  - Floating window support                       │</span></span>
<span class="line"><span>│  - Layout management (save/restore)             │</span></span>
<span class="line"><span>│  - Session persistence                           │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Terminal Emulator / PTY Layer                   │</span></span>
<span class="line"><span>│  - PTY allocation                                │</span></span>
<span class="line"><span>│  - Process execution                             │</span></span>
<span class="line"><span>│  - Output rendering                              │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br></div></div><h3 id="component-breakdown" tabindex="-1">Component Breakdown <a class="header-anchor" href="#component-breakdown" aria-label="Permalink to &quot;Component Breakdown&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th><th>Technology</th><th>Status</th></tr></thead><tbody><tr><td>undefined<strong>App</strong>undefined</td><td>Main Textual application</td><td>Textual</td><td>To design</td></tr><tr><td>undefined<strong>Menubar</strong>undefined</td><td>Top-level menu navigation</td><td>Textual Menu</td><td>To design</td></tr><tr><td>undefined<strong>Statusbar</strong>undefined</td><td>Real-time status display</td><td>Textual Footer</td><td>To design</td></tr><tr><td>undefined<strong>PaneManager</strong>undefined</td><td>Split/merge/layout logic</td><td>Custom Python</td><td>To implement</td></tr><tr><td>undefined<strong>TerminalPane</strong>undefined</td><td>PTY-based terminal widget</td><td>Textual TerminalWidget</td><td>To implement</td></tr><tr><td>undefined<strong>Session</strong>undefined</td><td>Persistent session state</td><td>YAML/JSON</td><td>To design</td></tr><tr><td>undefined<strong>Keyboard</strong>undefined</td><td>Shortcut handling</td><td>Textual key bindings</td><td>To implement</td></tr></tbody></table><hr><h2 id="design-decisions" tabindex="-1">Design Decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;Design Decisions&quot;">​</a></h2><h3 id="d1-framework-choice" tabindex="-1">D1: Framework Choice <a class="header-anchor" href="#d1-framework-choice" aria-label="Permalink to &quot;D1: Framework Choice&quot;">​</a></h3><p>undefined<strong>Decision</strong>: Use <strong>Textual</strong> for TUI framework undefined<strong>Rationale</strong>: Python stack alignment, CSS styling, rich widgets, active community undefined<strong>Alternatives Rejected</strong>: Ratatui (requires Rust), Bubble Tea (Go-only) undefined<strong>Tradeoff</strong>: Textual may be slightly slower than Rust alternatives, but alignment with thegent stack outweighs performance cost</p><h3 id="d2-terminal-pane-implementation" tabindex="-1">D2: Terminal Pane Implementation <a class="header-anchor" href="#d2-terminal-pane-implementation" aria-label="Permalink to &quot;D2: Terminal Pane Implementation&quot;">​</a></h3><p>undefined<strong>Decision</strong>: Use <strong>Textual TerminalWidget</strong> for embedded terminals undefined<strong>Rationale</strong>: Native Textual support, PTY integration, no external process needed undefined<strong>Alternatives Rejected</strong>: Zellij as compositor (more complex), tmux subprocess (harder to integrate) undefined<strong>Tradeoff</strong>: Embedded approach requires more development, but offers better integration</p><h3 id="d3-layout-persistence" tabindex="-1">D3: Layout Persistence <a class="header-anchor" href="#d3-layout-persistence" aria-label="Permalink to &quot;D3: Layout Persistence&quot;">​</a></h3><p>undefined<strong>Decision</strong>: Save layouts to <strong>YAML files</strong> in <code>~/.config/thegent/layouts/</code> undefined<strong>Rationale</strong>: Human-readable, version-control friendly, easy to template undefined<strong>Alternatives Rejected</strong>: JSON (more verbose), binary (not human-readable) undefined<strong>Tradeoff</strong>: YAML is slightly slower to parse, but benefits outweigh</p><h3 id="d4-session-model" tabindex="-1">D4: Session Model <a class="header-anchor" href="#d4-session-model" aria-label="Permalink to &quot;D4: Session Model&quot;">​</a></h3><p>undefined<strong>Decision</strong>: Use <strong>hierarchical session tree</strong> (workspace → pane group → pane) undefined<strong>Rationale</strong>: Matches tmux/Zellij concepts, supports complex layouts undefined<strong>Alternatives Rejected</strong>: Flat session list (less flexible) undefined<strong>Tradeoff</strong>: More complex state management, but more powerful</p><hr><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li>[ ] <strong>AC-1</strong>: App starts in &lt;500ms</li><li>[ ] <strong>AC-2</strong>: Menubar with File/Edit/View/Tools/Help menus fully functional</li><li>[ ] <strong>AC-3</strong>: Statusbar displays session name, agent status, real-time clock</li><li>[ ] <strong>AC-4</strong>: Can split panes horizontally and vertically; focus switching works</li><li>[ ] <strong>AC-5</strong>: Terminal panes execute shell commands and display output</li><li>[ ] <strong>AC-6</strong>: Keyboard shortcuts work (Ctrl+N=new pane, Ctrl+V=vsplit, Ctrl+X=close)</li><li>[ ] <strong>AC-7</strong>: Layouts can be saved to and restored from YAML</li><li>[ ] <strong>AC-8</strong>: Session state persists across app restart</li><li>[ ] <strong>AC-9</strong>: All linters pass (ruff, type checking); no new lint suppressions</li><li>[ ] <strong>AC-10</strong>: Test coverage ≥80% for compositor core logic</li></ul><hr><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>undefined<strong>Architecture</strong>: <a href="./design.html">../design.md</a></li><li>undefined<strong>Implementation Tasks</strong>: <a href="./tasks.html">../tasks.md</a></li><li>undefined<strong>Research</strong>: <a href="./../../research/CONVERSATION_DUMP_2026-02-16_EXPANDED.html">../../research/CONVERSATION_DUMP_2026-02-16_EXPANDED.md</a> § 2</li><li>undefined<strong>Related Work</strong>: <a href="./../../plans/UNIFIED_SYSTEM_APPLICATION_PLAN.html">../../plans/UNIFIED_SYSTEM_APPLICATION_PLAN.md</a></li><li>undefined<strong>Tech Stacks</strong>: <a href="./../../reference/TECHNOLOGY_STACK_AND_FRAMEWORKS.html">../../reference/TECHNOLOGY_STACK_AND_FRAMEWORKS.md</a></li></ul><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li>Textual Documentation: <a href="https://textual.textualize.io/" target="_blank" rel="noreferrer">https://textual.textualize.io/</a></li><li>Zellij Compositor: <a href="https://zellij.dev/" target="_blank" rel="noreferrer">https://zellij.dev/</a></li><li>tmux Reference: <a href="https://man7.org/linux/man-pages/man1/tmux.1.html" target="_blank" rel="noreferrer">https://man7.org/linux/man-pages/man1/tmux.1.html</a></li></ul>`,55)])])}const f=t(r,[["render",i]]);export{h as __pageData,f as default};
